// ============================================================
// Fashion store — the pure rules.
//
// Everything the fashion pages decide without React or the network: the
// category tree (three levels, cycle-safe), URL-backed listing state, the
// filter and sort rules, what a product card shows, and the per-combination
// stock matrix a size × colour catalogue needs. All of it runs in tests.
// ============================================================

export const MAX_DEPTH = 3;
/** The store column value every fashion row carries (catalogue_* since 0034). */
export const FASHION_STORE = 'fashion';
const num = (v) => { const n = Number(v); return Number.isFinite(n) ? n : 0; };
const str = (v) => String(v ?? '').trim();

// ---- Category tree ---------------------------------------------------------

/** Flat rows → a tree with lookups. Inactive rows are kept but flagged. */
export function buildTree(rows) {
  const list = (Array.isArray(rows) ? rows : []).map((r) => ({
    id: String(r.id), parent_id: r.parent_id == null ? null : String(r.parent_id),
    name: str(r.name), slug: str(r.slug), tagline: str(r.tagline), image_url: r.image_url || null,
    sort_order: num(r.sort_order), is_active: r.is_active !== false,
  }));
  const byId = new Map(list.map((n) => [n.id, n]));
  const childrenOf = new Map();
  for (const n of list) {
    const key = n.parent_id && byId.has(n.parent_id) ? n.parent_id : null;
    if (!childrenOf.has(key)) childrenOf.set(key, []);
    childrenOf.get(key).push(n);
  }
  const bySort = (a, b) => a.sort_order - b.sort_order || a.name.localeCompare(b.name);
  for (const arr of childrenOf.values()) arr.sort(bySort);
  const children = (id) => childrenOf.get(id == null ? null : String(id)) || [];
  const ancestors = (id) => {
    // root → … → node; stops on a cycle so a bad row cannot hang the page
    const out = []; const seen = new Set(); let cur = byId.get(String(id));
    while (cur && !seen.has(cur.id)) { seen.add(cur.id); out.unshift(cur); cur = cur.parent_id ? byId.get(cur.parent_id) : null; }
    return out;
  };
  const depth = (id) => ancestors(id).length;
  const descendants = (id) => {
    const out = []; const stack = [...children(id)]; const seen = new Set();
    while (stack.length) { const n = stack.shift(); if (seen.has(n.id)) continue; seen.add(n.id); out.push(n); stack.push(...children(n.id)); }
    return out;
  };
  return { list, byId, roots: children(null), children, ancestors, depth, descendants };
}

/** Would placing `id` under `parentId` keep the tree legal? Mirrors the SQL guard. */
export function validatePlacement(rows, { id = null, parentId = null } = {}) {
  const tree = buildTree(rows);
  const self = id == null ? null : String(id);
  let depth = 1; let cur = parentId == null ? null : String(parentId); const seen = new Set();
  while (cur) {
    if (self != null && cur === self) return { ok: false, reason: 'cycle' };
    if (seen.has(cur)) return { ok: false, reason: 'cycle' };
    seen.add(cur);
    depth += 1;
    if (depth > MAX_DEPTH) return { ok: false, reason: 'depth' };
    const node = tree.byId.get(cur);
    cur = node ? node.parent_id : null;
  }
  // Moving a branch carries its subtree with it.
  let height = 0;
  if (self != null) {
    const walk = (nid, lvl) => { for (const c of tree.children(nid)) { height = Math.max(height, lvl); walk(c.id, lvl + 1); } };
    walk(self, 1);
  }
  if (depth + height > MAX_DEPTH) return { ok: false, reason: 'depth' };
  return { ok: true, depth };
}

/** `/fashion/c/<slug>` → the shallowest active category with that slug. */
export function resolveCategory(tree, slug) {
  const s = str(slug).toLowerCase();
  if (!s) return null;
  const matches = tree.list.filter((n) => n.slug === s && n.is_active);
  if (matches.length === 0) return null;
  matches.sort((a, b) => tree.depth(a.id) - tree.depth(b.id) || a.sort_order - b.sort_order);
  return matches[0];
}

export const categoryHref = (node) => `/fashion/c/${node.slug}`;

export function breadcrumbFor(tree, node) {
  const trail = [{ name: 'Fashion', href: '/fashion' }];
  if (!node) return trail;
  for (const a of tree.ancestors(node.id)) trail.push({ name: a.name, href: categoryHref(a) });
  return trail;
}

/** The ids a listing for `node` covers: itself plus everything below it. */
export function categoryScope(tree, node) {
  if (!node) return null;
  return new Set([node.id, ...tree.descendants(node.id).map((n) => n.id)]);
}

// ---- Products ----------------------------------------------------------------

/** One product with its variants → what a card or a listing needs. */
export function productView(product, variants = null) {
  const vs = (Array.isArray(variants) ? variants : (product?.fashion_variants || []))
    .filter((v) => v && v.is_active !== false)
    .map((v) => ({
      id: String(v.id), size: str(v.size), colour: str(v.colour), colour_hex: v.colour_hex || null,
      sku: v.sku || null, stock: Math.max(0, num(v.stock)), price_override: v.price_override == null ? null : num(v.price_override),
      sort_order: num(v.sort_order),
    }))
    .sort((a, b) => a.sort_order - b.sort_order);
  const mrp = num(product?.mrp);
  const sale = product?.sale_price == null ? null : num(product.sale_price);
  const price = sale != null && sale < mrp ? sale : mrp;
  const discountPct = product?.discount_percent != null ? num(product.discount_percent)
    : (mrp > 0 && sale != null && sale < mrp ? Math.round(((mrp - sale) / mrp) * 100) : 0);
  const swatches = [];
  for (const v of vs) {
    let s = swatches.find((x) => x.colour === v.colour);
    if (!s) { s = { colour: v.colour, hex: v.colour_hex, stock: 0 }; swatches.push(s); }
    s.stock += v.stock;
  }
  const sizes = [...new Set(vs.map((v) => v.size))];
  const totalStock = vs.reduce((s, v) => s + v.stock, 0);
  return {
    id: String(product?.id ?? ''), slug: str(product?.slug), name: str(product?.name), brand: str(product?.brand),
    description: str(product?.description), category_id: product?.category_id == null ? null : String(product.category_id),
    image: Array.isArray(product?.images) && product.images[0] ? product.images[0] : null,
    images: Array.isArray(product?.images) ? product.images.filter(Boolean) : [],
    mrp, sale, price, discountPct, hasDiscount: discountPct > 0,
    rating: Math.max(0, Math.min(5, num(product?.rating))), reviewCount: Math.max(0, num(product?.review_count)),
    isNew: product?.is_new === true, isBestseller: product?.is_bestseller === true,
    sortOrder: num(product?.sort_order), variants: vs, swatches, sizes,
    inStock: vs.length === 0 ? false : totalStock > 0, totalStock,
    minPrice: vs.length ? Math.min(price, ...vs.filter((v) => v.price_override != null).map((v) => v.price_override)) : price,
  };
}

/** Per-combination stock: Medium/green can be out while Medium/navy is in. */
export function stockMatrix(view) {
  const cells = new Map();
  for (const v of view.variants) cells.set(`${v.size}�${v.colour}`, v);
  const get = (size, colour) => cells.get(`${size}�${colour}`) || null;
  return {
    sizes: view.sizes, colours: view.swatches.map((s) => s.colour),
    get,
    stock: (size, colour) => get(size, colour)?.stock ?? 0,
    inStock: (size, colour) => (get(size, colour)?.stock ?? 0) > 0,
    priceOf: (size, colour) => { const v = get(size, colour); return v && v.price_override != null ? v.price_override : view.price; },
    sizesInStockFor: (colour) => view.sizes.filter((s) => (get(s, colour)?.stock ?? 0) > 0),
  };
}

export function swatchOverflow(swatches, max = 4) {
  const list = Array.isArray(swatches) ? swatches : [];
  return { shown: list.slice(0, max), more: Math.max(0, list.length - max) };
}

// ---- Listing state in the URL ---------------------------------------------------

export const FASHION_SORTS = [
  { id: 'featured', label: 'Featured' },
  { id: 'price-asc', label: 'Price: low to high' },
  { id: 'price-desc', label: 'Price: high to low' },
  { id: 'discount', label: 'Biggest discount' },
  { id: 'rating', label: 'Top rated' },
  { id: 'new', label: 'Newest' },
];
export const FASHION_PRICE_BANDS = [
  { id: 'under-500', label: 'Under ₹500', min: 0, maxExclusive: 500 },
  { id: '500-999', label: '₹500 – ₹999', min: 500, maxExclusive: 1000 },
  { id: '1000-1999', label: '₹1,000 – ₹1,999', min: 1000, maxExclusive: 2000 },
  { id: '2000-plus', label: '₹2,000 & above', min: 2000, maxExclusive: Infinity },
];
export const DISCOUNT_STEPS = [10, 25, 40, 50];
export const RATING_STEPS = [4, 3];
export const VIEWS = ['grid', 'list'];

const SORT_IDS = new Set(FASHION_SORTS.map((s) => s.id));
const PRICE_IDS = new Set(FASHION_PRICE_BANDS.map((b) => b.id));
const list = (v) => String(v || '').split(',').map((x) => x.trim()).filter(Boolean);
const uniq = (arr) => [...new Set(arr)];

export function readFashionUrlState(searchParams) {
  const p = searchParams instanceof URLSearchParams ? searchParams : new URLSearchParams(searchParams || '');
  const discount = num(p.get('discount')); const rating = num(p.get('rating'));
  return {
    q: str(p.get('q')),
    sort: SORT_IDS.has(p.get('sort')) ? p.get('sort') : 'featured',
    price: PRICE_IDS.has(p.get('price')) ? p.get('price') : null,
    sizes: uniq(list(p.get('size'))),
    colours: uniq(list(p.get('colour'))),
    brands: uniq(list(p.get('brand'))),
    discount: DISCOUNT_STEPS.includes(discount) ? discount : null,
    rating: RATING_STEPS.includes(rating) ? rating : null,
    view: VIEWS.includes(p.get('view')) ? p.get('view') : 'grid',
  };
}

export function updateFashionUrlState(searchParams, patch) {
  const p = new URLSearchParams(searchParams);
  const has = (k) => Object.prototype.hasOwnProperty.call(patch, k);
  const setList = (key, arr) => { const v = uniq((Array.isArray(arr) ? arr : []).map(str).filter(Boolean)); if (v.length) p.set(key, v.join(',')); else p.delete(key); };
  if (has('q')) { const q = str(patch.q); if (q) p.set('q', q); else p.delete('q'); }
  if (has('sort')) { if (SORT_IDS.has(patch.sort) && patch.sort !== 'featured') p.set('sort', patch.sort); else p.delete('sort'); }
  if (has('price')) { if (PRICE_IDS.has(patch.price)) p.set('price', patch.price); else p.delete('price'); }
  if (has('sizes')) setList('size', patch.sizes);
  if (has('colours')) setList('colour', patch.colours);
  if (has('brands')) setList('brand', patch.brands);
  if (has('discount')) { if (DISCOUNT_STEPS.includes(num(patch.discount))) p.set('discount', String(num(patch.discount))); else p.delete('discount'); }
  if (has('rating')) { if (RATING_STEPS.includes(num(patch.rating))) p.set('rating', String(num(patch.rating))); else p.delete('rating'); }
  if (has('view')) { if (patch.view === 'list') p.set('view', 'list'); else p.delete('view'); }
  return p;
}

export function activeFilterCount(state) {
  return (state.price ? 1 : 0) + state.sizes.length + state.colours.length + state.brands.length + (state.discount ? 1 : 0) + (state.rating ? 1 : 0);
}

/** The choices the panel offers, from what is actually in the listing. */
export function filterOptions(views) {
  const sizes = new Map(); const colours = new Map(); const brands = new Map();
  for (const v of views) {
    for (const s of v.sizes) sizes.set(s, (sizes.get(s) || 0) + 1);
    for (const s of v.swatches) if (!colours.has(s.colour)) colours.set(s.colour, s.hex);
    if (v.brand) brands.set(v.brand, (brands.get(v.brand) || 0) + 1);
  }
  const sizeOrder = ['XS', 'S', 'M', 'L', 'XL', 'XXL'];
  const sortSizes = (a, b) => { const ia = sizeOrder.indexOf(a); const ib = sizeOrder.indexOf(b); if (ia >= 0 && ib >= 0) return ia - ib; if (ia >= 0) return -1; if (ib >= 0) return 1; return a.localeCompare(b, 'en', { numeric: true }); };
  return {
    sizes: [...sizes.keys()].sort(sortSizes),
    colours: [...colours.entries()].map(([colour, hex]) => ({ colour, hex })).sort((a, b) => a.colour.localeCompare(b.colour)),
    brands: [...brands.keys()].sort(),
  };
}

export function matchesFilters(view, state) {
  if (state.q) {
    const q = state.q.toLowerCase();
    if (!`${view.name} ${view.brand} ${view.description}`.toLowerCase().includes(q)) return false;
  }
  if (state.price) {
    const band = FASHION_PRICE_BANDS.find((b) => b.id === state.price);
    if (band && !(view.price >= band.min && view.price < band.maxExclusive)) return false;
  }
  if (state.sizes.length && !state.sizes.some((s) => view.sizes.includes(s))) return false;
  if (state.colours.length && !state.colours.some((c) => view.swatches.some((s) => s.colour === c))) return false;
  if (state.brands.length && !state.brands.includes(view.brand)) return false;
  if (state.discount && view.discountPct < state.discount) return false;
  if (state.rating && view.rating < state.rating) return false;
  return true;
}

export function sortViews(views, sort) {
  const arr = [...views];
  const featured = (a, b) => (b.isBestseller - a.isBestseller) || (b.isNew - a.isNew) || (a.sortOrder - b.sortOrder) || a.name.localeCompare(b.name);
  switch (sort) {
    case 'price-asc': return arr.sort((a, b) => a.price - b.price || featured(a, b));
    case 'price-desc': return arr.sort((a, b) => b.price - a.price || featured(a, b));
    case 'discount': return arr.sort((a, b) => b.discountPct - a.discountPct || featured(a, b));
    case 'rating': return arr.sort((a, b) => b.rating - a.rating || b.reviewCount - a.reviewCount || featured(a, b));
    case 'new': return arr.sort((a, b) => (b.isNew - a.isNew) || (a.sortOrder - b.sortOrder));
    default: return arr.sort(featured);
  }
}

export function applyListing(views, state, scope = null) {
  const inScope = scope ? views.filter((v) => v.category_id && scope.has(v.category_id)) : views;
  return sortViews(inScope.filter((v) => matchesFilters(v, state)), state.sort);
}

/** Distinct brands across the catalogue, most products first — the "Top Brands" row. */
export function topBrands(views, limit = 6) {
  const count = new Map();
  for (const v of views) if (v.brand) count.set(v.brand, (count.get(v.brand) || 0) + 1);
  return [...count.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])).slice(0, limit).map(([name, products]) => ({ name, products }));
}

// ---- Admin writes: omit-when-absent -------------------------------------------
// Mirrors adminImportBiosashCatalog: a key the caller did not mention is not
// sent, so PostgREST's ON CONFLICT DO UPDATE leaves the live value alone.
// The one exception is `store`: every row is stamped FASHION_STORE, whatever
// the caller passed — the catalogue tables require it, and a fashion write
// can never land in another store.
const pick = (input, map) => {
  const row = { store: FASHION_STORE };
  for (const [from, to] of Object.entries(map)) if (Object.prototype.hasOwnProperty.call(input, from)) row[to] = input[from];
  row.store = FASHION_STORE;
  return row;
};
export const fashionCategoryToRow = (input) => pick(input || {}, {
  id: 'id', parentId: 'parent_id', name: 'name', slug: 'slug', tagline: 'tagline', imageUrl: 'image_url',
  sortOrder: 'sort_order', isActive: 'is_active', isDemo: 'is_demo',
});
export const fashionProductToRow = (input) => pick(input || {}, {
  id: 'id', name: 'name', slug: 'slug', brand: 'brand', description: 'description', categoryId: 'category_id',
  mrp: 'mrp', salePrice: 'sale_price', images: 'images', rating: 'rating', reviewCount: 'review_count',
  sku: 'sku', hsnCode: 'hsn_code', gstRate: 'gst_rate', netContent: 'net_content', stock: 'stock',
  isActive: 'is_active', isNew: 'is_new', isBestseller: 'is_bestseller', sortOrder: 'sort_order', isDemo: 'is_demo',
});
export const fashionVariantToRow = (input) => pick(input || {}, {
  id: 'id', productId: 'product_id', size: 'size', colour: 'colour', colourHex: 'colour_hex', sku: 'sku',
  stock: 'stock', priceOverride: 'price_override', isActive: 'is_active', sortOrder: 'sort_order', isDemo: 'is_demo',
});
